<?php
// Program-owned articles; visibility settings and posts are stored separately.
function systemUpdateArticles(){return array_merge(json_decode('[{"id": "update-r56", "title": "掲示板をはっきり点滅・右から左へスクロールする表示に変更", "bodyHtml": "<ul><li>今日の動き・青教室の点滅を、1秒周期で表示と非表示が切り替わる形にしました。</li><li>スクロールは右から左へ1行で流れる電光掲示板風に変更しました。</li><li>保存済みの指示とアニメーション設定は引き継ぎます。</li></ul>", "createdAt": "2026-09-17T02:46:22+09:00", "updatedAt": "2026-09-17T02:46:22+09:00", "author": "システム更新", "audience": "admin", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 136}]',true),json_decode('[{"id": "update-r55", "title": "掲示板の生徒表示確認・強調と時間割の日付欄を改善しました", "bodyHtml": "<ul><li>今日の動き・青教室で「生徒表示を確認」が使えます。</li><li>掲示の行ごとに強調・ゆっくりした点滅・長文スクロール・編集・削除ができます。モニターの端に余白を設けました。</li><li>全体時間割の日付欄を開閉でき、学校行事や欠席・遅刻連絡を確認できます。</li><li>準備済みの授業は、チェックで消す代わりに薄く表示します。</li><li>共有メモの通知・TODO、並び替え、CODEXメモの最小化など、前回分も含みます。</li></ul>", "createdAt": "2026-09-17T02:04:19+09:00", "updatedAt": "2026-09-17T02:04:19+09:00", "author": "システム更新", "audience": "admin", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 135}]',true),json_decode('[{"id": "update-r54", "title": "共有メモの通知・TODO一覧と並び替えを追加しました", "bodyHtml": "<ul><li>新しい共有メモを担当講師のお知らせに未読表示します。</li><li>共有メモをTODOにし、担当・期間・状態で確認できます。完了者と日時を記録します。</li><li>未記録一覧は授業名クリックでクラスを絞れます。カルテは新しい順・古い順を選べます。</li><li>テスト結果は成績の高い順を初期表示にしました。</li><li>ページ右下のCODEXメモ確認欄を最小化でき、同じブラウザでは状態を記憶します。</li></ul>", "createdAt": "2026-09-16T12:39:02+09:00", "updatedAt": "2026-09-16T12:39:02+09:00", "author": "システム更新", "audience": "admin", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 134}]',true),json_decode('[{"id": "update-r53", "title": "テスト結果のコピーと新規入力・記録画面の操作を改善しました", "bodyHtml": "<ul><li>テスト結果と詳細へのリンクをコピーし、カルテから開けるようにしました。</li><li>「成績・テスト結果入力」から新規入力を直接開きます。</li><li>連結詳細のカルテ一覧リンク、削除ボタンの下部配置を改善しました。</li><li>未記録一覧に古い順・新しい順を追加しました。</li><li>CODEXメモに差し戻しの状態を追加しました。</li></ul>", "createdAt": "2026-09-16T12:13:55+09:00", "updatedAt": "2026-09-16T12:13:55+09:00", "author": "システム更新", "audience": "admin", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 133}]',true),json_decode('[{"id": "update-r52", "title": "テスト未報告の確認・入力と記録画面を改善しました", "bodyHtml": "<ul><li>テスト結果に未報告・免除を追加。生徒の予定表と講師の未報告一覧に案内します。</li><li>前回授業の曜日・終了時刻・経過日数と時間を表示します。</li><li>未記録一覧で期間を絞り、チェックした授業を未定として一括記録できます。</li><li>連結授業の削除ボタンを下部左側へ移しました。</li><li>CODEXメモは未対応の古い順で表示し、完了表記を対応完了に統一しました。</li></ul>", "createdAt": "2026-09-16T11:37:46+09:00", "updatedAt": "2026-09-16T11:37:46+09:00", "author": "システム更新", "audience": "admin", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 132}]',true),json_decode('[{"id": "update-r51", "title": "テスト結果の記録と授業の入力・メモ管理を改善しました", "bodyHtml": "<ul><li>生徒ごとに複数のテスト結果を記録し、一覧で確認できます。</li><li>管理者は未記入の必須項目を「未定」で記録できます。出欠に「不明」を追加し、欠席・遅刻・免除を色で表示します。</li><li>前回の連結授業の宿題を次の授業に表示し、連結削除ボタンを上部へ移しました。</li><li>今日の動き・青教室の表示画面でドラッグして順番を変更できます。</li><li>日付欄の幅を修正し、比較日には曜日を表示します。</li><li>CODEXメモに検証中・保留、状態の絞り込み、昇順・降順と管理者メニューのリンクを追加しました。</li></ul>", "createdAt": "2026-09-16T02:43:38+09:00", "updatedAt": "2026-09-16T02:43:38+09:00", "author": "システム更新", "audience": "admin", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 131}]',true),json_decode('[{"id": "update-r50", "title": "日付比較・連結表示・掲示入力を改善しました", "bodyHtml": "<ul><li>コマ生成で2日を上下に比較し、連結状態も引き継いでコピーできます。</li><li>学校のテストを14日前から案内し、全体時間割の保存後の位置と管理者の削除操作を改善しました。</li><li>今日の動き・青教室で直接追加と並べ替えができ、全画面では操作部分を隠します。</li><li>クラス別カルテの過去記録をスクロールで追加表示します。</li><li>CODEXメモに今回の回答を残し、検証待ちを色で表示します。相談コードをクリックしてコピーできます。</li></ul>", "createdAt": "2026-09-15T20:00:38+09:00", "updatedAt": "2026-09-15T20:00:38+09:00", "author": "システム更新", "audience": "admin", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 130}]',true),json_decode('[{"id": "update-r49", "title": "未記録の案内とCODEXメモの回答履歴を追加しました", "bodyHtml": "<ul><li>連結詳細で出欠・カルテ・宿題の未記入箇所をハイライトし、必要な入力を案内します。途中までの保存もできます。</li><li>管理者は未記録一覧で日付・講師・クラスなどを絞り込み、選択した授業を通知から一括除外できます。出欠・カルテはそのまま残し、除外は解除できます。</li><li>CODEXメモに質問の種類、回答・対応結果、相談コードを追加しました。履歴をコピーしてCodexに貼り付けると、同じ内容を続けて相談できます。今回いただいた4件の回答・対応結果も記載しました。</li></ul>", "createdAt": "2026-09-15", "updatedAt": "2026-09-15", "author": "システム更新", "audience": "admin", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 129}]',true),json_decode('[{"id": "update-r48", "title": "カルテ一覧と連結授業の記録画面を整理しました", "bodyHtml": "<ul><li>カルテ一覧を「カルテを見る」「未記録を確認」に分けました。検索・絞り込みや返信は必要なときに開けます。</li><li>赤い未記録件数はログイン中の先生の担当授業だけを数えます。管理者は自分の担当と担当未設定の授業が対象です。管理者が全講師の一覧を開いても、赤い件数の対象は変わりません。</li><li>連結詳細は出欠・カルテ・宿題の入力欄をまとめ、保存済みの記録状況を上部に表示します。入退室・生徒からの連絡・共有メモは参考情報として整理しました。</li><li>管理者向けに、入退室アプリの生徒を対応づける手順を画面内に追加しました。</li></ul>", "createdAt": "2026-09-15", "updatedAt": "2026-09-15", "author": "システム更新", "audience": "admin", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 128}]',true),json_decode('[{"id": "update-r47", "title": "CODEXメモの修正確認と新規メモを選びやすくしました", "bodyHtml": "<ul><li>メモ一覧から元のページを開くと、CODEXメモ欄に「修正確認中」と対象のメモを表示します。</li><li>「対策完了」で確認した管理者・日時を記録し、未対応の一覧から隠します。「追記」で同じメモに検証結果を追加できます。</li><li>いつもの「✎ CODEXメモ」アイコンは、修正確認中でも新規メモで開きます。</li></ul>", "createdAt": "2026-09-15", "updatedAt": "2026-09-15", "author": "システム更新", "audience": "admin", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 127}]',true),json_decode('[{"id": "update-r46", "title": "CODEXメモに検証結果を追記できます", "bodyHtml": "<ul><li>CODEXメモを書くときに「新規メモ」「既存メモに追記」を選べます。</li><li>一覧の「このメモに追記」、元のページの「検証結果を追記」から、同じメモに文章・画像を追加できます。追記してもメモの件数は増えません。</li><li>元の文章・画像を残し、追記した管理者・日時も記録します。一括コピーと画像付きZIPにも追記を含めます。</li><li>対応済みのメモに追記すると未対応に戻ります。修正が確認できたら、改めて対応済みにしてください。</li></ul>", "createdAt": "2026-09-15", "updatedAt": "2026-09-15", "author": "システム更新", "audience": "admin", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 126}]',true),json_decode('[{"id": "update-r45", "title": "給与・入退室欄・勤務NGの表示を改善しました", "bodyHtml": "<ul><li>勤務OK・NGの①〜⑪に開始・終了時刻を表示します。</li><li>給与の通常一覧・給与総計では、管理設定で対象外とした講師を除外します。講師欄で対象の先生を選ぶと、単価の設定と参考額の確認ができます。</li><li>給与の授業名を押すと、選択した期間・講師の授業詳細を表示します。連結授業はひとまとめに表示し、給与は元のコマ数で計算します。</li><li>授業詳細の玄関の入退室記録は最初は折りたたみ、見出しを押すと開閉できます。30秒ごとの確認は継続します。</li><li>未連携・記録なしは通常の案内として表示します。管理者は同じ欄の「生徒の対応を設定」から、氏名・塾籍番号を確認して連携できます。</li><li>未記録通知はログイン中の先生の担当授業だけが対象です。担当未設定の授業は管理者に通知します。対象の説明も表示しました。</li></ul>", "createdAt": "2026-09-15", "updatedAt": "2026-09-15", "author": "システム更新", "audience": "admin", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 123}]',true),[['id'=>'update-r44','title'=>'通知・共有メモ・今日の案内を改善しました','bodyHtml'=>'<p>CODEXメモでいただいた改善を反映しました。</p><ul><li>担当授業の未記入をカルテの赤い件数でも表示します。担当未設定は管理者に通知します。</li><li>連絡・要望をこのページへまとめました。記事の表示ON/OFF、トラブル・来客の未読件数、月謝の預かり報告にも対応します。</li><li>勤務OK・NGは講師本人の分だけ閲覧・変更できます。管理者は全員分を確認できます。</li><li>今日の動き・青教室に画像付きの案内を追加でき、モニターで指定秒数ごとに切り替えられます。</li><li>先生共有メモは非表示・再表示でき、全体時間割で過去を追加しても見ている位置を保ちます。</li><li>先生ログイン時は生徒予定表の最初の確認を省略し、未連携の入退室はその状態を明示します。</li></ul>','createdAt'=>'2026-09-15','updatedAt'=>'2026-09-15','author'=>'システム更新','audience'=>'admin','color'=>'blue','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>122],['id'=>'update-r43','title'=>'管理者用のCODEXメモを追加しました','bodyHtml'=>'<p>管理者ログイン中は各ページの「CODEXメモ」から文章・画像を記録できます。ページURL・記入者・日時を自動で残します。</p><ul><li>一覧の「未対応を一括コピー」で指示をコピーし、Codexへ貼り付けられます。画像は「画像付きZIP」でまとめて渡せます。</li><li>「元のページを開く」で修正を確認し、「修正を確認・対応済み」で未対応一覧から非表示にできます。</li><li>対応済みのメモも保持し、「対応済みも表示」から確認・再開できます。コピーやページを開くだけでは対応済みになりません。</li></ul><p><a href="codex_memos.php">CODEXメモ一覧を開く</a></p>','createdAt'=>'2026-09-15','updatedAt'=>'2026-09-15','author'=>'システム更新','audience'=>'admin','color'=>'blue','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>121],['id'=>'update-r42','title'=>'モニターで非表示の指示を完全に隠します','bodyHtml'=>'<p>「今日の動き」と「青教室の指示」のモニター表示では、「表示」のチェックを外した行を完全に隠します。管理者で開いていても、薄い行や余白は残しません。</p><p>再表示したいときは「編集」を開き、その行の「表示する」にチェックを入れて保存してください。非表示の内容は削除されず、30秒ごとの自動確認も引き続き行います。</p>','createdAt'=>'2026-09-14','updatedAt'=>'2026-09-14','author'=>'システム更新','audience'=>'admin','color'=>'blue','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>120],['id'=>'update-r41','title'=>'遅刻・欠席連絡の送信前にβ版の確認を表示','bodyHtml'=>'<p>「連絡を送信」を押すと、β版・試験運用中であることを強調した確認画面を表示します。</p><p>塾長からこの機能の利用開始の説明があるまでは、電話またはLINEでも連絡が必要です。「確認して送信」を押した場合にアプリへ送信します。「戻る」では送信せず、入力内容を残します。</p>','createdAt'=>'2026-09-14','updatedAt'=>'2026-09-14','author'=>'システム更新','audience'=>'admin','color'=>'amber','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>119],['id'=>'update-r40','title'=>'遅刻・欠席連絡のβ版案内と更新履歴の公開設定','bodyHtml'=>'<p>遅刻・欠席連絡はβ版・試験運用中です。塾長からこの機能の利用開始の説明があるまでは、アプリから送信した場合も、電話またはLINEでの連絡が必要です。</p><ul><li>授業カード、送信画面、送信後の画面、送信済みの確認画面にβ版の案内を表示します。</li><li>送信ボタンの近くにも案内を残し、スクロール中でも確認できます。</li><li>自動追加される更新履歴の初期公開先を「管理者のみ」にしました。内容を確認してから「公開先・色を変更」で必要な対象へ公開してください。</li><li>すでに管理者が保存した公開先は維持します。記事を読むだけでは公開されません。</li></ul>','createdAt'=>'2026-09-14','updatedAt'=>'2026-09-14','author'=>'システム更新','audience'=>'admin','color'=>'amber','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>118],['id'=>'update-r39','title'=>'生徒ページの上部と、今日の動きの場所表示を整理しました','bodyHtml'=>'<p>生徒の予定表の上部は、小さな名前・塾籍番号と「今日の動き」「塾からのお知らせ」のリンクにまとめました。各リンクから別ページを開き、同じ生徒の予定表へ戻れます。</p><ul><li>生徒名の変更欄、絞り込み条件、送信済み連絡の一覧は、予定表の上部に表示しません。</li><li>日付移動や補助メニューは「日付・メニュー」から開けます。</li><li>今日の動きと青教室の指示では、場所の白い囲みをなくし、文字と小さな色印で表示します。背景になじむ見た目にしました。</li></ul>','createdAt'=>'2026-09-14','updatedAt'=>'2026-09-14','author'=>'システム更新','audience'=>'everyone','color'=>'blue','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>117],['id'=>'update-r38','title'=>'生徒情報の保存エラーに対応しました','bodyHtml'=>'<p>生徒情報の所属学校・住所・追加情報の保存処理を見直しました。学校名だけの登録や、入退室アプリの塾籍番号を参照した状態でも保存できます。</p><ul><li>保存時にサーバーの応答を読み取れない場合は、日本語で案内し、入力内容を残します。</li><li>保存後に応答が途切れた場合は、登録内容を確認してから結果を表示します。</li><li>入退室アプリの番号は引き続き参照し、学校などの保存で変更しません。</li></ul><p><a href="student_manage.html">生徒管理を開く</a></p>','createdAt'=>'2026-09-14','updatedAt'=>'2026-09-14','author'=>'システム更新','audience'=>'admin','color'=>'green','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>116],['id'=>'update-r37','title'=>'生徒の予定表の上部をコンパクトにしました','bodyHtml'=>'<p>生徒の予定表は、名前・塾籍番号と連絡先のリンクを上部にまとめました。「日付・メニュー」で過去の日付や補助メニューを開けます。</p><ul><li>生徒名は初回に入力して「決定」またはEnterで決めます。決定後は小さく表示し、ページ内で変更できません。</li><li>「今日の動き」と「塾からのお知らせ」はアイコン付きリンクから別ページへ。お知らせには未読件数を表示します。</li><li>絞り込み条件と、送信済み遅刻・欠席連絡の一覧を上部から外しました。送信済みの連絡は該当授業の「この授業の連絡を確認」から開けます。</li><li>入退室アプリで対応づけ済みの塾籍番号を、生徒の予定表・生徒管理・生徒情報に表示します。</li></ul><p><a href="student.html">生徒の予定表を開く</a></p>','createdAt'=>'2026-09-14','updatedAt'=>'2026-09-14','author'=>'システム更新','audience'=>'everyone','color'=>'blue','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>115],['id'=>'update-r36','title'=>'入退室の読み込みエラーに対応しました','bodyHtml'=>'<p>入退室データの読み取りを、古いサーバー環境にも対応する処理へ変更しました。読み込めない場合は、原因の確認に使うコードを表示します。</p><p>「生徒の対応を設定」に「生徒一覧を再読み込み」を追加しました。一覧を取得できるまで保存・候補選択は無効になります。再読み込みに失敗した場合も、入力中の対応を残します。</p><p>玄関の入退室記録を取得しても、授業の出欠は自動で変更しません。講師が確認して保存してください。</p><p><a href="presence.html">入退室を確認</a></p>','createdAt'=>'2026-09-14','updatedAt'=>'2026-09-14','author'=>'システム更新','audience'=>'teachers','color'=>'blue','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>114],['id'=>'update-r35','title'=>'教室への連絡と入退室の確認を便利にしました','bodyHtml'=>'<ul><li><strong>連結した授業にも生徒へのメッセージ。</strong>連結詳細の入力欄で編集し「まとめて保存」すると、生徒の予定表に表示されます。</li><li><strong>今日の動きに教室の選択・自由文・表示チェック。</strong>場所は色やアイコン付きで選べます。時刻などが不要な連絡も登録でき、管理者はチェックで表示を切り替えられます。</li><li><strong>青教室専用の掲示画面。</strong>全体向けとは別の内容を登録できます。タイトルを編集でき、背景はグレーを初期色として選択できます。掲示は30秒ごとに自動確認します。</li><li><strong>玄関の入退室を出欠確認の参考に。</strong>「入退室」の一覧と授業の出欠画面から記録を確認できます。前日以前の記録には要確認と表示します。出欠の確定・保存は講師が行います。</li></ul><p>初回は管理者が「入退室」→「生徒の対応を設定」で、時間割と玄関アプリの生徒を確認してください。</p><p><a href="daily_board.html">今日の動き</a> ／ <a href="room_board.html?mode=monitor">青教室の指示</a> ／ <a href="presence.html">入退室を確認</a></p>','createdAt'=>'2026-09-14','updatedAt'=>'2026-09-14','author'=>'システム更新','audience'=>'teachers','color'=>'blue','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>113],['id'=>'update-r34','title'=>'今日の動きの保存エラーを修正','bodyHtml'=>'<p>「今日の動き」を保存するとエラーになる環境に対応しました。管理者の「公開して保存」から登録・更新できます。</p><p>表示中の指示は30秒ごとに最新情報を自動確認します。管理者が保存した変更は、開いている生徒の予定表・専用ページ・モニター表示にも反映されます。更新からの経過時間と確認日時も表示します。</p><p><a href="daily_board.html">今日の動きを開く</a></p>','createdAt'=>'2026-09-14','updatedAt'=>'2026-09-14','author'=>'システム更新','audience'=>'teachers','color'=>'blue','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>112],['id'=>'update-r33','title'=>'今日の動きをモニターとスマホで共有','bodyHtml'=>'<p>教室での細かい指示を、時間割と一緒に確認できます。</p><ul><li><strong>開始時刻・対象・場所・指示を一覧に。</strong>生徒の縦型予定表と、上部メニューの「今日の動き」に同じ内容を表示します。</li><li><strong>更新からの経過時間を表示。</strong>30秒ごとに最新情報を確認し、通信できない場合は最後に取得した内容であることを表示します。</li><li><strong>教室モニター用の表示。</strong>「モニター表示」で大きな文字の横並び一覧に切り替えられます。通常表示では日付を選んで過去の指示も確認できます。</li><li><strong>編集は管理者のみ。</strong>「編集」から指示を追加・変更・削除し、「公開して保存」で全員に反映します。保存ボタンはスクロール中も表示します。</li></ul><p>授業の出欠や入退室の状態とは別の案内です。</p><p><a href="daily_board.html">今日の動きを開く</a></p>','createdAt'=>'2026-09-14','updatedAt'=>'2026-09-14','author'=>'システム更新','audience'=>'teachers','color'=>'blue','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>111],['id'=>'update-r32','title'=>'コマ生成で過去の日付を開きやすくしました','bodyHtml'=>'<p>コマ生成の上部メニューを折りたたんだときも、カレンダー上部に日付の操作を表示するようにしました。</p><ul><li>「日付へ移動」で9/14などの見たい日を指定すると、その日を先頭に表示します。</li><li>「前の7日」で過去の期間を広げ、「今日に戻る」で今日からの表示に戻せます。</li><li>連結処理から戻った後も、選び直した日付で再読み込みできます。連結直後の日付へ勝手に戻るのを防ぎます。</li></ul>','createdAt'=>'2026-09-13','updatedAt'=>'2026-09-13','author'=>'システム更新','audience'=>'teachers','color'=>'blue','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>109],['id'=>'update-r31','title'=>'連結授業の延長時に食事休憩を選べます','bodyHtml'=>'<p>「後ろへ1コマ延長」の確認画面に「延長後の食事休憩」を追加しました。現在の設定が最初に選ばれています。</p><ul><li>食事休憩を入れる場合は「あり」を選んで「1コマ延長する」を押します。生徒・講師の予定表に「途中で食事休憩が入ります」と案内します。</li><li>「なし」を選ぶと、延長後の連結授業に食事休憩の案内を表示しません。</li><li>新しいコマを作る場合も、配置済みの次のコマを取り込む場合も選べます。給与は連結したコマ数で計算します。</li></ul>','createdAt'=>'2026-09-13','updatedAt'=>'2026-09-13','author'=>'システム更新','audience'=>'teachers','color'=>'green','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>108],['id'=>'update-r30','title'=>'次のコマが配置済みでも、そのまま延長できます','bodyHtml'=>'<p>管理者の「後ろへ1コマ延長」を改善しました。次の時間番号に同じ授業が既にある場合は、そのコマを連結へ取り込んで延長できます。別の選択画面へ移る必要はありません。</p><ul><li>例：⑤⑥の後ろに⑦が配置済みなら、⑤⑥⑦へまとめます。⑦を二重に作成しません。</li><li>既存コマの出欠・確定・準備状態を引き継ぎます。カルテ・宿題は共通記録へ追記し、元の返信・資料も残します。</li><li>次のコマが空いている場合は、従来どおり新しいコマを作って延長します。</li><li>次のコマが別の連結に含まれる場合や、同じ授業が複数ある場合は、対象の確認を案内します。</li></ul>','createdAt'=>'2026-09-13','updatedAt'=>'2026-09-13','author'=>'システム更新','audience'=>'teachers','color'=>'green','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>107],['id'=>'update-r29','title'=>'連結した授業を1コマ延長できます','bodyHtml'=>'<p>管理者は、連結した授業の詳細にある「後ろへ1コマ延長」から、次のコマを新しく作って延長できます。たとえば⑨⑩を⑨⑩⑪にできます。</p><ul><li>延長後のコマ・終了時刻・給与のコマ数を確認し、「1コマ延長する」で保存します。</li><li>カルテと宿題は共通のままです。追加したコマは未確定・未準備・出欠未記録になります。</li><li>全体時間割から開いた場合は全体時間割に、コマ生成からの場合はコマ生成に戻ります。</li><li>次のコマの講師NGや教室の重複は確認を表示します。⑪より先へ延長することはできません。</li></ul>','createdAt'=>'2026-09-13','updatedAt'=>'2026-09-13','author'=>'システム更新','audience'=>'teachers','color'=>'green','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>106],['id'=>'update-r28','title'=>'カルテ・連結授業の操作を改善、生徒宛てのお知らせに対応','bodyHtml'=>'<ul><li>カルテは直近7日間で終了した授業を初期表示します。「過去7日を追加」「先の7日を追加」や日付指定で表示範囲を変えられます。担当講師・記録作成・最終編集を区別し、ボタンの重なりも修正しました。</li><li>連結カードの確定アイコンを通常コマと統一しました。管理者は連結したまま全コマを移動でき、連結詳細の「コマを追加して連結」から前後の単独コマを追加できます。全体時間割から連結した場合は全体時間割に戻ります。</li><li>連絡欄で同じ授業を二重に指定した際のエラーを修正しました。クラスを変更した際、空欄の共有メモが原因で保存後に詳細が閉じない問題も修正しています。</li><li>管理者はお知らせの公開先に「指定した生徒宛て」を選び、1人または複数の生徒に案内できます。生徒の縦型予定表の上部と、お知らせページに表示します。先生もお知らせページで確認できます。</li><li>お知らせに表示終了日を設定できます。指定日の23:59まで表示し、翌日から通常一覧に表示しません。管理者は「期限切れも表示」で確認・編集できます。</li></ul><p>生徒宛てのお知らせは、選択した氏名に応じた表示です。生徒本人のログインによる限定公開ではありません。</p>','createdAt'=>'2026-09-13','updatedAt'=>'2026-09-13','author'=>'システム更新','audience'=>'teachers','color'=>'green','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>105],['id'=>'update-r27','title'=>'連結カードの表示と確定・準備の操作を整理','bodyHtml'=>'<ul><li>全体時間割の連結授業を、時間帯いっぱいの横長カードにしました。左に授業名・担当・時間、右に確定と準備のアイコンをまとめて表示します。</li><li>全体時間割・講師別の連結カードでは、確定・準備はそれぞれ1つです。操作すると連結した全コマにまとめて反映します。確定の変更は管理者が行います。</li><li>以前の設定がコマごとに異なる場合は「一部」と表示します。押すと全コマを設定済みにし、全コマが設定済みのときに押すと解除します。</li><li>「準備完了を非表示」で連結の一部だけを表示している場合も、操作は連結した全コマに反映します。出欠・カルテの記録と給与のコマ数は変わりません。</li></ul>','createdAt'=>'2026-09-13','updatedAt'=>'2026-09-13','author'=>'システム更新','audience'=>'teachers','color'=>'blue','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>104],['id'=>'update-r25','title'=>'担当授業の未記入をお知らせ・NG設定へ直接移動','bodyHtml'=>'<ul><li>終了した担当授業の出欠・カルテ・宿題の未記入を、更新履歴・お知らせにまとめて表示します。未記入のある授業数を上部メニューの赤い件数に加算します。</li><li>出欠を登録・カルテを記入・宿題を記入から、その授業の入力欄へ進めます。保存すると残っている未記入に合わせて通知が減ります。連結授業は1件です。</li><li>宿題がない日は「宿題なしを入力」を押して保存してください。過去の宿題の空欄も未記入として表示します。</li><li>日付の講師OK・NG一覧から「勤務OK・NGを設定」で、その日の設定を開けます。管理者は先生の名前から、その先生の設定へ進めます。</li></ul>','createdAt'=>'2026-09-12','updatedAt'=>'2026-09-12','author'=>'システム更新','audience'=>'teachers','color'=>'amber','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>103],['id'=>'update-r24','title'=>'生徒から遅刻・欠席を連絡できます','bodyHtml'=>'<ul><li>生徒の授業カードから遅刻・欠席を連絡できます。連結授業は対象のコマを選べます。</li><li>出欠は仮受付し、講師が内容を確認して確定します。</li><li>欠席した授業内容に取り組む予定は、指定日に教室で取り組む・取り組まない・その他から選び、後日でも登録できます。</li><li>更新履歴・お知らせに生徒からの連絡を表示し、未読を赤い件数バッジで知らせます。記事の既読と「みました」は分けて記録します。</li></ul>','createdAt'=>'2026-09-12','updatedAt'=>'2026-09-12','author'=>'システム更新','audience'=>'teachers','color'=>'amber','published'=>true,'revision'=>1,'builtin'=>true,'kind'=>'update','sortOrder'=>102]],json_decode('[{"id": "update-r23", "title": "予定の案内と連結表示を改善・お知らせを投稿できます", "bodyHtml": "<ul><li>授業が入っていない日は、今日から14日先まで「現在調整中」、それより先は「未定」と表示します。塾の休講日指定はOFF、過去のOFFはそのままです。</li><li>全体時間割の連結コマを短くまとめ、続く時間帯を細い線で表示します。確定・準備済みは各コマのアイコンから変更できます。</li><li>学校登録で保存できない問題を修正しました。通信に失敗した場合は、入力内容を残して日本語で状況を表示します。</li><li>更新履歴は記事カードの一部を表示し、押すと詳細を開きます。管理者は公開先と色を変更し、新しい案内・お知らせを投稿できます。「みました」で確認を記録できます。</li></ul>", "createdAt": "2026-09-12", "updatedAt": "2026-09-12", "author": "システム更新", "audience": "teachers", "color": "green", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 101}, {"id": "update-r22", "title": "参加クラスに「自由参加」を追加・先生共有メモの読み込みを修正", "bodyHtml": "<ul><li><strong>生徒ごとに「自由参加」を設定。</strong>生徒の予定表と詳細に「参加は自由ですが、講師は参加を勧めています。」と表示します。同じ時間に優先度の高い授業があれば、そちらを表示します。優先度が同じなら両方を表示します。</li><li><strong>共有メモの読み込みを改善。</strong>サーバー環境によって応答が空になる問題を修正しました。通信に失敗した場合も、入力中の文章を残して日本語で状況を表示します。「共有メモを再読み込み」で確認し、投稿をやり直せます。</li></ul><details class=\\"update-admin\\"><summary>自由参加の設定方法（管理者向け）</summary><p>生徒管理の「参加クラスの設定」で、適用日と「自由参加」を選んで保存します。一覧では緑色で表示します。クラス名を押して免除にし、もう一度押すと自由参加に戻せます。</p><p>優先度は「クラス優先度」から設定します。数字が大きい授業を優先し、自由参加に変更しても数字は変わりません。これまでの出欠・カルテは残ります。</p></details>", "createdAt": "2026-09-12", "updatedAt": "2026-09-12", "author": "システム更新", "audience": "teachers", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 100}, {"id": "update-r21", "title": "連結授業を選びやすく、時間割でもひとまとまりに", "bodyHtml": "<ul><li><strong>全体時間割・生徒別・講師別の表示を連結。</strong>全体時間割は複数コマにまたがる1枚の授業、生徒別・講師別の縦型予定表は「⑨⑩」のようにコマ番号と時間帯をまとめて表示します。免除や絞り込みで表示しないコマは含めません。給与は元のコマ数のままです。</li><li><strong>連結時に食事休憩の有無を選択。</strong>「あり」にすると、予定表に「途中で食事休憩が入ります」と表示します。複製と同時に連結する場合も選べます。</li><li><strong>コマのエリア全体で選択・解除。</strong>小さなチェックボックスを狙わず、コマ名や余白を押して選べます。選択中は色が変わります。「現在のカルテを確認」は、選択を変えずに開けます。</li><li><strong>連結後はコマ生成へ。</strong>選んだ日付のコマ生成に戻ります。複数コマへの複製と同時に連結した場合も同じです。共通の詳細は、必要なときにコマや🔗から開けます。</li></ul>", "createdAt": "2026-09-12", "updatedAt": "2026-09-12", "author": "システム更新", "audience": "teachers", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 99}, {"id": "update-r20", "title": "コマの移動・複製と授業連結を使いやすく", "bodyHtml": "<ul><li><strong>別の日へのドラッグで「移動・コピー」を選択。</strong>コマ生成・全体時間割で使えます。移動は元のコマと記録を移し、コピーは元を残して予定を追加します。</li><li><strong>次のコマへまとめて複製。</strong>詳細の「次のコマへ複製（複数可）」でコマ数を選べます。「元の授業と複製したコマを連結する」にチェックすれば、一度に連結できます。</li><li><strong>コマ上の🔗から連結。</strong>同じ日・同じクラス・講師・教室・授業内容の連続したコマを選びます。連結後の🔗やコマを押すと、共通の詳細が開きます。</li><li><strong>出席・カルテ・報告や返信を1つに。</strong>連結した授業の出欠は1つの欄でまとめて保存できます。すでにコマごとに違う出欠がある場合は内容を表示し、選択するまで変更しません。連結前の記録は履歴に残ります。</li></ul><p>給与は連結前のコマ数で計算します。例えば4コマを連結しても4コマ分です。コピー先に元の出欠・カルテ・準備済み・確定状態は引き継ぎません。操作は管理者が行います。</p>", "createdAt": "2026-09-12", "updatedAt": "2026-09-12", "author": "システム更新", "audience": "teachers", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 98}, {"id": "update-r19", "title": "管理者のページ移動とクラス優先度の変更", "bodyHtml": "<ul><li><strong>管理者は各ページの共通メニューから移動。</strong>生徒の予定表やお知らせページでも、コマ生成・生徒管理・給与などへ直接移動できます。メニューはスクロール中も画面上に残り、狭い画面では左右に動かせます。</li><li><strong>生徒管理に「クラス優先度」を追加。</strong>生徒ごとにクラスの数字を変更して保存できます。授業時間が重なったときは数字の大きいクラスを生徒の予定表に表示し、同じ数字なら両方を表示します。</li></ul><p>優先度は過去を含め予定表全体に反映します。出欠の記録・参加期間・免除設定は変わりません。設定は管理者が行います。</p>", "createdAt": "2026-09-12", "updatedAt": "2026-09-12", "author": "システム更新", "audience": "teachers", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 97}, {"id": "update-r18", "title": "学校行事・お知らせ・共有メモを使いやすく", "bodyHtml": "<ul><li><strong>予定表に学校行事を表示。</strong>テストや修学旅行、文化祭などを期間で登録できます。生徒の予定表には、その生徒の所属学校の行事だけを自動表示します。先生の予定表では学校を選んで絞り込めます。</li><li><strong>塾のお知らせを全員に表示。</strong>日付の表示を押すと、お知らせページで内容と画像を見られます。授業がない日も確認できます。</li><li><strong>先生共有メモを発言ごとに記録。</strong>ログインした先生の名前と発言日時が付きます。チェックで完了にすると、完了した先生と日時も記録します。チェックを外した履歴も残ります。以前の共有メモは、発言者・日時が未記録のまま残し、完了チェックを付けられます。</li><li><strong>「前の授業と同じ出席」を追加。</strong>同じ日・同じクラスの直前のコマから、記録済みの出欠を入力欄へコピーします。現在免除中の生徒や前のコマに記録がない生徒は変更しません。内容を確認し、いつもの保存ボタンで確定してください。「出席未入力」からの確認にも、全員出席と前の授業の出欠をコピーするボタンがあります。非表示の生徒は出欠入力欄に表示せず、保存済みの過去の出欠は残します。</li><li><strong>全体時間割の上部メニューを固定。</strong>下へスクロールしても、コマ生成・全体時間割・カルテなどのメニューを画面上に残します。画面が狭い場合は、メニューを左右に動かして他の項目を選べます。</li></ul><details class=\\"update-admin\\"><summary>管理者向け：登録方法</summary><p>「学校・お知らせ管理」で学校名と行事・お知らせを登録します。生徒管理の所属学校を登録した学校名に合わせてください。公開のチェックを入れると、生徒・保護者も閲覧できます。学校名変更後も旧学校名との対応を引き継ぎます。</p></details><div class=\\"update-links\\"><a class=\\"ws-button\\" href=\\"notices.html\\">学校行事・お知らせを見る</a></div>", "createdAt": "2026-09-12", "updatedAt": "2026-09-12", "author": "システム更新", "audience": "teachers", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 96}, {"id": "update-r16", "title": "トラブル・来客を報告できるようになりました", "bodyHtml": "<ul><li><strong>「トラブル・来客」から報告を作成。</strong>発生日時・種類・場所・関係者・内容・対応したことを記録できます。報告者にはログインした先生の名前が付きます。</li><li><strong>投稿者が閲覧範囲を選択。</strong>「先生全員」か「管理者と投稿者だけ」を必ず選んで投稿します。本文・追記・変更履歴に適用されます。</li><li><strong>対応状況と追記を共有。</strong>未対応・対応中・対応済み・記録のみを切り替え、その後の対応を追記できます。本文の編集は報告者と管理者が行い、変更履歴も残ります。</li><li><strong>種類・日付・対応状況で絞り込み。</strong>件名・内容・関係者などから検索できます。閲覧できない報告は検索結果や件数にも含まれません。</li><li><strong>カルテのリアクションは返信ごとに。</strong>本文へのボタンを外し、各返信の下に「この返信にリアクション」と表示しました。</li></ul><div class=\\"update-links\\"><a class=\\"ws-button\\" href=\\"incident_reports.php\\">トラブル・来客を報告</a><a class=\\"ws-button\\" href=\\"lesson_records.html\\">カルテを開く</a></div>", "createdAt": "2026-09-11", "updatedAt": "2026-09-11", "author": "システム更新", "audience": "teachers", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 95}, {"id": "update-r15", "title": "カルテの日付・出欠・やりとりを見やすく", "bodyHtml": "\\n<ul><li><strong>日付に曜日と経過日数を表示。</strong>「今日」「3日前」などで、いつの授業か分かりやすくなりました。</li><li><strong>出席・欠席・遅刻ごとに生徒名を表示。</strong>未記録の生徒がいるときは「出欠を記録してください。」から、その授業の出欠入力へ進めます。連結した授業は、コマごとの出欠が違う場合も確認できます。</li><li><strong>カルテ本文と返信にリアクション。</strong>👍・❤️・😊・🙏から選んで押せます。同じものをもう一度押すと取り消し、別のものを押すと変更できます。「誰がリアクションしたか」で先生の名前も確認できます。</li><li><strong>この更新履歴ページを追加。</strong>上部メニューの「更新履歴」から、いつでも確認できます。</li></ul>\\n<div class=\\"update-links\\"><a class=\\"ws-button\\" href=\\"lesson_records.html\\">カルテを開く</a><a class=\\"ws-button\\" href=\\"teacher2026summer.html\\">全体時間割を開く</a></div>", "createdAt": "2026-09-11", "updatedAt": "2026-09-11", "author": "システム更新", "audience": "teachers", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 94}, {"id": "update-r9-r14", "title": "クラス選び・生徒管理の操作を改善", "bodyHtml": "<p>管理者が予定を組んだり、生徒の参加状態を変更したりするときの操作を改善しました。</p><details class=\\"update-admin\\"><summary>管理者向けの変更点を見る</summary><ul><li>コマ生成の詳細で、クラスを学年別のツリーから選べます。最初はすべて開いた状態で、名前検索も使えます。</li><li>生徒管理のクラス名を押すと、今日からの「参加中 ⇄ 免除」を切り替えられます。免除中も薄く表示され、もう一度押せば参加中に戻せます。</li><li>非表示に設定した授業は、生徒管理の参加クラス一覧から省きます。</li><li>コマ生成の日付を押すと、講師のOK・NGをポップアップで確認できます。</li><li>日付横の鍵をONにすると、その日の確定済みのコマが半透明になり、操作できなくなります。未確定の予定を探しやすくする表示切り替えで、鍵をOFFにすると元に戻ります。</li></ul></details>", "createdAt": "2026-09-11", "updatedAt": "2026-09-11", "author": "システム更新", "audience": "teachers", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 93}, {"id": "update-r1-r8", "title": "ログイン・勤務予定・授業の記録を改善", "bodyHtml": "<ul><li><strong>自分のアカウントでログイン。</strong>投稿や記録には、ログインした先生の名前が付きます。</li><li><strong>勤務できる日時を自分で登録。</strong>「勤務OK・NG」では、NGを選ぶ方法と、勤務できるOKだけを選ぶ方法を切り替えられます。今日から7日先までの変更は管理者に通知されます。</li><li><strong>「準備済み」と「確定」を分けて表示。</strong>準備済みは授業準備の状態、確定は授業予定の状態です。生徒側にも確定した授業を表示します。</li><li><strong>全員出席のボタンを追加。</strong>出欠入力画面で一括選択し、必要な生徒だけ変更して保存できます。</li><li><strong>連続する授業をまとめて記録。</strong>管理者が連結した授業は、⑨⑩などの共通カルテから入力できます。</li><li><strong>全体時間割に現在時刻の赤い線。</strong>コマからの詳細表示や、準備済みを隠す操作も改善しました。</li><li><strong>連絡・要望を一覧で共有。</strong>対応が終わったものには、解決済みのチェックを付けられます。</li></ul><div class=\\"update-links\\"><a class=\\"ws-button\\" href=\\"availability.html\\">勤務OK・NG</a><a class=\\"ws-button\\" href=\\"staff_requests.html\\">連絡・要望</a></div><details class=\\"update-admin\\"><summary>管理者向けの変更点を見る</summary><ul><li>クラス名の変更と、クラス名・参加生徒をコピーして編集する複製機能を追加しました。</li><li>生徒の参加・免除・参加終了を、適用日を指定して変更できます。生徒情報には塾籍番号・学校・住所などを登録できます。</li><li>コマ生成・クラス管理・生徒管理・給与は管理者専用になりました。</li><li>先週のコピー方法を選択でき、PC教室の同時授業や、確認のうえでの教室共有にも対応しました。</li></ul></details>", "createdAt": "2026-09-10", "updatedAt": "2026-09-10", "author": "システム更新", "audience": "teachers", "color": "blue", "published": true, "revision": 1, "builtin": true, "kind": "update", "sortOrder": 92}]',true));}
